def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Extend diagonal strokes from their existing aligned seeds to the edges.
    for color in set(x for row in grid for x in row) - {bg}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1, 1), (1, -1)):
            # Extend a stroke only from a contiguous diagonal pair.
            for r, c in cells:
                if (r + dr, c + dc) not in cells:
                    continue
                rr, cc = r, c
                while 0 <= rr - dr < h and 0 <= cc - dc < w and grid[rr-dr][cc-dc] == color:
                    rr -= dr
                    cc -= dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == bg:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out

